import { randomBytes } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

// Keeps the books in memory and mirrors every change to a JSON file.
// Writes go to a temp file first and are renamed into place, so a crash
// mid-write can't leave a half-written books.json behind.
export async function openStore(file) {
  const books = await load(file);
  let pending = Promise.resolve();

  function save() {
    const snapshot = JSON.stringify(books, null, 2) + '\n';
    // Chain writes so they never overlap and always land in order.
    pending = pending.then(async () => {
      await mkdir(dirname(file), { recursive: true });
      const tmp = `${file}.tmp`;
      await writeFile(tmp, snapshot);
      await rename(tmp, file);
    });
    return pending;
  }

  return {
    all() {
      return books.slice();
    },

    get(id) {
      return books.find((b) => b.id === id);
    },

    async add({ title, author, notes }) {
      const book = {
        id: newId(),
        title,
        author,
        notes,
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await save();
      return book;
    },

    async finish(id) {
      const book = books.find((b) => b.id === id);
      if (!book) return undefined;
      if (!book.finishedAt) {
        book.finishedAt = new Date().toISOString();
        await save();
      }
      return book;
    },
  };
}

async function load(file) {
  let text;
  try {
    text = await readFile(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  // Deliberately let a JSON parse error crash startup: silently starting
  // empty would overwrite the user's list on the next save.
  const data = JSON.parse(text);
  if (!Array.isArray(data)) {
    throw new Error(`${file} should contain a JSON array of books`);
  }
  return data;
}

function newId() {
  // Short, URL-safe and unguessable enough for a shareable link.
  return randomBytes(6).toString('base64url');
}

