const MAX_BODY_BYTES = 64 * 1024;
const MAX_TITLE = 300;
const MAX_AUTHOR = 300;
const MAX_NOTES = 20000;

export function createHandler(store) {
  return async function handle(req, res) {
    try {
      await route(store, req, res);
    } catch (err) {
      if (err instanceof HttpError) {
        sendPage(res, err.status, page('Error', `<p>${escape(err.message)}</p><p><a href="/">Back to my books</a></p>`));
        return;
      }
      console.error(err);
      sendPage(res, 500, page('Error', '<p>Something went wrong.</p><p><a href="/">Back to my books</a></p>'));
    }
  };
}

async function route(store, req, res) {
  const { pathname } = new URL(req.url, 'http://localhost');
  const method = req.method;

  if (pathname === '/') {
    if (method !== 'GET' && method !== 'HEAD') return methodNotAllowed(res, 'GET');
    return sendPage(res, 200, homePage(store.all()));
  }

  if (pathname === '/books') {
    if (method !== 'POST') return methodNotAllowed(res, 'POST');
    const form = await readForm(req);
    const { values, errors } = validateBook(form);
    if (errors.length) {
      return sendPage(res, 400, homePage(store.all(), { values, errors }));
    }
    const book = await store.add(values);
    return redirect(res, `/books/${encodeURIComponent(book.id)}`);
  }

  let m = pathname.match(/^\/books\/([^/]+)$/);
  if (m) {
    if (method !== 'GET' && method !== 'HEAD') return methodNotAllowed(res, 'GET');
    const book = store.get(decodeURIComponent(m[1]));
    if (!book) throw new HttpError(404, 'That book isn’t on the list.');
    return sendPage(res, 200, bookPage(book));
  }

  m = pathname.match(/^\/books\/([^/]+)\/finish$/);
  if (m) {
    if (method !== 'POST') return methodNotAllowed(res, 'POST');
    const book = await store.finish(decodeURIComponent(m[1]));
    if (!book) throw new HttpError(404, 'That book isn’t on the list.');
    const form = await readForm(req);
    // Send the user back to wherever they clicked the button from.
    return redirect(res, form.get('back') === 'book' ? `/books/${encodeURIComponent(book.id)}` : '/');
  }

  throw new HttpError(404, 'Page not found.');
}

export function validateBook(form) {
  const values = {
    title: (form.get('title') ?? '').trim(),
    author: (form.get('author') ?? '').trim(),
    notes: (form.get('notes') ?? '').replace(/\r\n/g, '\n').trim(),
  };
  const errors = [];
  if (!values.title) errors.push('Please enter a title.');
  if (values.title.length > MAX_TITLE) errors.push(`Title must be at most ${MAX_TITLE} characters.`);
  if (values.author.length > MAX_AUTHOR) errors.push(`Author must be at most ${MAX_AUTHOR} characters.`);
  if (values.notes.length > MAX_NOTES) errors.push(`Notes must be at most ${MAX_NOTES} characters.`);
  return { values, errors };
}

// ---------- pages ----------

function homePage(books, { values = {}, errors = [] } = {}) {
  const reading = books
    .filter((b) => !b.finishedAt)
    .sort((a, b) => b.addedAt.localeCompare(a.addedAt));
  const finished = books
    .filter((b) => b.finishedAt)
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  const readingItems = reading.map(
    (b) => `<li>
      ${bookLink(b)}
      <form method="post" action="/books/${attr(encodeURIComponent(b.id))}/finish" class="inline">
        <button type="submit">Mark finished</button>
      </form>
    </li>`,
  );
  const finishedItems = finished.map(
    (b) => `<li>${bookLink(b)} <span class="muted">finished ${formatDate(b.finishedAt)}</span></li>`,
  );

  return page(
    'My books',
    `<h1>My books</h1>

    <section>
      <h2>Currently reading</h2>
      ${list(readingItems, 'Nothing on the go right now.')}
    </section>

    <section>
      <h2>Finished</h2>
      ${list(finishedItems, 'No finished books yet.')}
    </section>

    <section>
      <h2 id="add">Add a book</h2>
      ${errors.length ? `<ul class="errors">${errors.map((e) => `<li>${escape(e)}</li>`).join('')}</ul>` : ''}
      <form method="post" action="/books" class="add">
        <label>Title <input name="title" required maxlength="${MAX_TITLE}" value="${attr(values.title ?? '')}"></label>
        <label>Author <input name="author" maxlength="${MAX_AUTHOR}" value="${attr(values.author ?? '')}"></label>
        <label>Notes <textarea name="notes" rows="4" maxlength="${MAX_NOTES}">${escape(values.notes ?? '')}</textarea></label>
        <button type="submit">Add book</button>
      </form>
    </section>`,
  );
}

function bookPage(book) {
  const status = book.finishedAt
    ? `<p class="muted">Finished ${formatDate(book.finishedAt)}</p>`
    : `<p class="muted">Currently reading</p>
       <form method="post" action="/books/${attr(encodeURIComponent(book.id))}/finish">
         <input type="hidden" name="back" value="book">
         <button type="submit">Mark finished</button>
       </form>`;

  return page(
    book.title,
    `<p><a href="/">← My books</a></p>
    <h1>${escape(book.title)}</h1>
    <p class="author">${book.author ? `by ${escape(book.author)}` : '<span class="muted">Unknown author</span>'}</p>
    ${status}
    <h2>Notes</h2>
    ${book.notes ? `<div class="notes">${escape(book.notes)}</div>` : '<p class="muted">No notes.</p>'}`,
  );
}

function bookLink(b) {
  const by = b.author ? ` <span class="muted">by ${escape(b.author)}</span>` : '';
  return `<a href="/books/${attr(encodeURIComponent(b.id))}">${escape(b.title)}</a>${by}`;
}

function list(items, emptyText) {
  return items.length ? `<ul class="books">${items.join('')}</ul>` : `<p class="muted">${escape(emptyText)}</p>`;
}

function page(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  h1 { margin-bottom: 0.25rem; }
  h2 { margin-top: 2rem; font-size: 1.2rem; }
  a { color: #1a5fb4; }
  .muted { color: #666; }
  .author { font-size: 1.1rem; margin-top: 0; }
  ul.books { padding-left: 1.2rem; }
  ul.books li { margin: 0.4rem 0; }
  form.inline { display: inline; margin-left: 0.5rem; }
  form.add { display: grid; gap: 0.75rem; }
  form.add label { display: grid; gap: 0.2rem; }
  input, textarea { font: inherit; padding: 0.35rem; }
  button { font: inherit; cursor: pointer; }
  form.add button { justify-self: start; }
  .notes { white-space: pre-wrap; background: #f6f6f6; padding: 0.75rem 1rem; border-radius: 4px; }
  .errors { color: #b00020; }
</style>
</head>
<body>
${body}
</body>
</html>
`;
}

// ---------- helpers ----------

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

async function readForm(req) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) throw new HttpError(413, 'That’s too much text.');
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

function sendPage(res, status, html) {
  res.writeHead(status, {
    'Content-Type': 'text/html; charset=utf-8',
    'Content-Length': Buffer.byteLength(html),
  });
  res.end(res.req?.method === 'HEAD' ? undefined : html);
}

function redirect(res, location) {
  // 303 so the browser follows up with a GET and a refresh won't resubmit.
  res.writeHead(303, { Location: location });
  res.end();
}

function methodNotAllowed(res, allow) {
  res.writeHead(405, { Allow: allow, 'Content-Type': 'text/plain; charset=utf-8' });
  res.end('Method not allowed');
}

function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

export function escape(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const attr = escape;

